/* Purple Tiger 90 by Webdevava — https://uiverse.io/Webdevava/purple-tiger-90 */
button {
  background: #111;
  border: none;
  padding: 10px 14px;
  border-radius: 6px;
  color: #fff;
  font-size: 30px;
}

button:hover {
  border: 3px solid #fff;
  transform: rotate3d(0, 1, 0.5, 360deg);
  transition: 1.5s;
}
